function setup() {
	createCanvas(1240, 720);
	// noLoop() removed for animationnoStroke()
}

function keyPressed() {
	saveCanvas('caterpillar', 'png')
}

function draw() {
	let cols = prepareColors(palette)
	for(let i = 0; i < 500; i++) {
		let baseSize
		do {
			baseSize = 120 * pow(random(), 4)
		} while(baseSize < 5)
		let col1 = floor(random(cols.length))
		let col2
		do {
			col2 = floor(random(cols.length))
		} while(col1 == col2)
		curveLine(width * random(-0.5, 1), height * random(-0.1, 1.1), baseSize * 10, baseSize, [cols[col1], cols[col2]])
	}
}

function curveLine(_x, _y, _l, _w, _cols) {
	push()
	let dots = []
	let sinOffset = random(TAU)
	for(let progressX = 0; progressX <= _l; progressX += 1) {
		let offsetY = sin( (progressX / 750 * TAU) + sinOffset) * 60
		let currentWidth = _w / 6 + _w * 5/6 * sinEasing(progressX / _l)

		dots.push({
			x: _x + progressX,
			y: _y + offsetY,
			size: currentWidth
		})
	}

	// メインのシェイプを描く
	for(let lineDot of dots) {
		fill(_cols[0])
		circle(lineDot.x, lineDot.y, lineDot.size)
	}
	// 模様を描く
	for(let i = 0; i < dots.length; i++) {
		fill(_cols[1])
		circle(dots[i].x, dots[i].y + dots[i].size * 0.5, dots[i].size * 0.2)
	}
	pop()
}

function sinEasing(amt) {
	return pow(sin(PI * constrain(amt, 0, 1)), 0.5)
}

function prepareColors() {
	var cols = []
	for(let colcode of palette) {
		cols.push(color(colcode))
	}
	return cols
}
